add_filter( 'woocommerce_is_purchasable', 'perfectpixel_vacation_purchasable', 999 );
add_filter( 'woocommerce_variation_is_purchasable', 'perfectpixel_vacation_purchasable', 999 );
add_action( 'wp_body_open', 'perfectpixel_vacation_notice' );

function perfectpixel_vacation_active() {
	$today = current_time( 'Y-m-d' );
	$from  = trim( '{{vacation_from}}' );
	$to    = trim( '{{vacation_to}}' );
	return ( '' === $from || $today >= $from ) && ( '' === $to || $today <= $to );
}

function perfectpixel_vacation_purchasable( $purchasable ) {
	return perfectpixel_vacation_active() ? false : $purchasable;
}

function perfectpixel_vacation_notice() {
	if ( perfectpixel_vacation_active() ) {
		echo '<div class="perfectpixel-vacation-notice" role="status" style="background:#1d2327;color:#fff;text-align:center;padding:.75em 1em;font-size:.95em">' . esc_html( '{{vacation_message}}' ) . '</div>';
	}
}
